  "returncode": 0,
  "output": "<% content_for(:title, "Quizzy · Quizzes") %>
<header class="admin-header">
  <span class="logo"><span class="logo__mark">?</span>Quizzy</span>
  <span class="admin-header__tag">Moderator</span>
</header>

<main class="admin-main">
  <div class="page-head">
    <div>
      <h1>Quizzes</h1>
    </div>
    <div class="buttons">
      <a class="btn btn--pink" href="<%= new_moderate_quiz_path %>">New quiz</a>
      <a class="btn btn--ghost" href="<%= moderate_import_path %>">Import quiz</a>
    </div>
  </div>

  <% if @quizzes.any? %>
    <ul class="quiz-list">
      <% @quizzes.each do |quiz| %>
        <li class="card quiz-tile">
          <h3><a href="<%= moderate_quiz_path(quiz) %>"><%= h quiz.title %></a></h3>
          <div class="meta"><%= quiz.questions.count %> questions · <%= quiz.questions.where(active: true).count %> active</div>
          <div class="buttons mt-2">
            <a class="btn btn--sm" href="<%= moderate_quiz_path(quiz) %>">Open</a>
            <a class="btn btn--sm btn--ghost" href="<%= edit_moderate_quiz_path(quiz) %>">Settings</a>
          </div>
        </li>
      <% end %>
    </ul>
  <% else %>
    <div class="empty">No quizzes yet. Create your first quiz to get started.</div>
  <% end %>
</main>
=====APPLICATION CONTROLLER=====
class ApplicationController < ActionController::Base
end
